import 'dart:convert';
import 'dart:typed_data';

/// In-memory embedded chain logos for chains that need to be guaranteed
/// available even across Shorebird OTA code-push patches where newly added APK
/// assets cannot be distributed without a fresh APK installation.
class EmbeddedChainLogos {
  EmbeddedChainLogos._();

  static final Map<int, Uint8List> _cache = {};

  static Uint8List? forChainId(int chainId) {
    final cached = _cache[chainId];
    if (cached != null) return cached;

    final b64 = _base64ForChainId(chainId);
    if (b64 == null) return null;

    final bytes = base64Decode(b64);
    _cache[chainId] = bytes;
    return bytes;
  }

  static String? _base64ForChainId(int chainId) => switch (chainId) {
    5042 => _arcLogoBase64,
    _ => null,
  };

  static const String _arcLogoBase64 =
      '';
}
